// Hook info (volatile — rebuilt on compact/clear, NOT persisted in projectContext)
private hookInfo: Message[] = [];

/**
 * Set hook info (pending + legacy hooks). Stored in a separate volatile
 * array, NOT projectContext — this info changes as hooks are compiled or
 * skills change, and must be refreshable. Rebuilt on compact/clear by the
 * caller (hook-bootstrap or llm.ts) querying ConditionRegistry fresh.
 * 
 * Injected in getMessages() after projectContext but before conversation,
 * so it's part of the cached prefix. Cache is only broken when this info
 * actually changes — which happens at compact/clear boundaries that already
 * invalidate the cache.
 */
setHookInfo(messages: Message[]): void {
  this.hookInfo = messages;
}

/**
